            int lowBound = 0, highBound = 9, nextVal;
            if (tempArr[j] != '_') {
                lowBound = highBound = tempArr[j] - '0';
            } else if (j == 0) {
                lowBound++;
            }

            for (int prevMod = 0; prevMod < 25; prevMod++) {
                for (int digitVal = lowBound; digitVal <= highBound; digitVal++) {
                    nextVal = (prevMod * 10 + digitVal) % 25;
                    dpState[currentState][nextVal] += dpState[currentState ^ 1][prevMod];
                }
            }
            currentState ^= 1;
        }
        totalWays += dpState[currentState ^ 1][0];
        if (!hasXFlag) break;
    }

    if (len == 1 && (s[0] == '_' || s[0] == 'X' || s[0] == '0')) totalWays++;
    cout << totalWays << "\n";

